# -----------------------------------------------------------------------------
# Host-allowlist для блока http в nginx — обычный HTTP на порту 80.
#
# СГЕНЕРИРОВАНО автоматически из services.yaml — не правьте руками.
# Разрешено 490 доменов в 11 категориях. Дата: 2026-08-05
#
# Подключается внутрь map в nginx.conf:
#     map $host $http_upstream {
#         hostnames;
#         default  "";
#         include  /etc/nginx/geoblock/nginx-host-allow.map;
#     }
#
# Пустой default обязателен. Без него сервер на 80-м порту становится открытым
# HTTP-прокси: достаточно прислать «GET http://любой-хост/ HTTP/1.1»
# в absolute-form, и nginx возьмёт $host прямо из строки запроса. Через такой
# прокси гоняют спам и сканирование, а в логах жертвы будет ваш адрес.
#
# Список совпадает с nginx-sni-allow.map — те же домены, другое значение.
# -----------------------------------------------------------------------------

